import { getMediaType } from './getMediaType.js';
// Only these media types may render inline on the application's origin.
// Unknown or active content must download as an attachment.
const INLINE_MEDIA_TYPES = new Set([
    'application/font-woff',
    'audio/aac',
    'audio/flac',
    'audio/mp4',
    'audio/mpeg',
    'audio/ogg',
    'audio/wav',
    'audio/webm',
    'font/otf',
    'font/ttf',
    'font/woff',
    'font/woff2',
    'image/avif',
    'image/bmp',
    'image/gif',
    'image/jpeg',
    'image/png',
    'image/vnd.microsoft.icon',
    'image/webp',
    'image/x-icon',
    'video/mp4',
    'video/mpeg',
    'video/ogg',
    'video/quicktime',
    'video/webm'
]);
export function shouldAttachMedia(upstreamHeaders) {
    const mediaType = getMediaType(upstreamHeaders);
    return !mediaType || !INLINE_MEDIA_TYPES.has(mediaType);
}
